#!/usr/bin/env python3
"""hooks-of-node-module.py <folder>: ONE CASE A FOLDER: THE HOOKS OF node:module THAT PACKAGES USE TO STEP BETWEEN A require AND ITS FILE (require.extensions: pirates, @babel/register, ts-node, nyc . Module._load: proxyquire, mock-require . Module._resolveFilename: module-alias, tsconfig-paths . Module.prototype.require: require-in-the-middle . Module._cache | require.cache written to: stubs . Module.wrap . module._compile . Module.registerHooks): a compiled program has resolved and bound its requires at the build: whatever plain Bun lets such a hook see or change must be seen or changed, or refused in words."""
import os, sys
out = sys.argv[1]; cases = {}
LIB = 'exports.name = "the real lib"; exports.dep = require("./dep.js").name;\n'
DEP = 'exports.name = "the real dep";\n'
HEAD = 'const Module = require("node:module"); const path = require("node:path");\nconst say = (...v) => console.log(...v.map(x => typeof x === "string" ? x : JSON.stringify(x)));\nconst attempt = f => { try { return f(); } catch (e) { return "THROWS " + e.name + ": " + String(e.message).split("\\n")[0].slice(0, 70); } };\n'
def case(name, body, more=None): cases[name] = {"main.js": HEAD + body + "\n", "lib.js": LIB, "dep.js": DEP, **(more or {})}
case("an-extension-handler-that-looks-on", 'const old = require.extensions[".js"]; const seen = [];\nrequire.extensions[".js"] = function (module, filename) { seen.push(path.basename(filename)); return old(module, filename); };\nsay(require("./lib.js"), seen);')
case("an-extension-handler-set-after-the-first-load", 'say(require("./dep.js")); const old = require.extensions[".js"]; const seen = [];\nrequire.extensions[".js"] = function (module, filename) { seen.push(path.basename(filename)); return old(module, filename); };\nsay(require("./lib.js"), seen);')
case("an-extension-handler-that-compiles-another-text", 'const old = require.extensions[".js"];\nrequire.extensions[".js"] = function (module, filename) { if (filename.endsWith("dep.js")) return module._compile(\'exports.name = "a text of the handler";\', filename); return old(module, filename); };\nsay(require("./lib.js"));')
case("an-extension-handler-that-wraps-compile", 'const old = require.extensions[".js"];\nrequire.extensions[".js"] = function (module, filename) { const compile = module._compile; module._compile = function (code, name) { return compile.call(this, code.replace("the real", "the rewritten"), name); }; return old(module, filename); };\nsay(require("./lib.js"));')
case("an-extension-handler-taken-away-again", 'const old = require.extensions[".js"]; const seen = [];\nrequire.extensions[".js"] = function (module, filename) { seen.push(path.basename(filename)); return old(module, filename); };\nsay(require("./dep.js")); require.extensions[".js"] = old; say(require("./lib.js"), seen);')
case("a-new-extension", 'require.extensions[".txt2"] = function (module, filename) { module.exports = "read by the handler: " + require("node:fs").readFileSync(filename, "utf8").trim(); };\nsay(attempt(() => require("./note.txt2")));', {"note.txt2": "a note\n"})
case("load-is-replaced", 'const old = Module._load; const seen = [];\nModule._load = function (request, parent, isMain) { seen.push(request); if (request === "./dep.js") return { name: "a stub from _load" }; return old.apply(this, arguments); };\nsay(require("./lib.js"), seen); Module._load = old;')
case("resolve-filename-replaced", 'const old = Module._resolveFilename; const seen = [];\nModule._resolveFilename = function (request, ...rest) { seen.push(request); if (request === "./dep.js") request = "./other.js"; return old.call(this, request, ...rest); };\nsay(require("./lib.js"), seen); Module._resolveFilename = old;', {"other.js": 'exports.name = "the other dep";\n'})
case("an-alias-by-resolve-filename", 'const old = Module._resolveFilename;\nModule._resolveFilename = function (request, ...rest) { if (request.startsWith("@alias/")) request = path.join(__dirname, request.slice(7)); return old.call(this, request, ...rest); };\nsay(attempt(() => require("@alias/lib.js")));')
case("an-alias-used-inside-a-required-file", 'const old = Module._resolveFilename;\nModule._resolveFilename = function (request, ...rest) { if (request.startsWith("@alias/")) request = path.join(__dirname, request.slice(7)); return old.call(this, request, ...rest); };\nsay(attempt(() => require("./user.js")));', {"user.js": 'exports.name = "user"; exports.lib = require("@alias/lib.js").name; exports.again = require("@alias/dep.js") === require("./dep.js");\n'})
case("an-alias-over-a-package-that-exists", 'const old = Module._resolveFilename;\nModule._resolveFilename = function (request, ...rest) { if (request === "pkg") request = path.join(__dirname, "dep.js"); return old.call(this, request, ...rest); };\nsay(attempt(() => require("pkg").name), attempt(() => require("./user.js")));', {"user.js": 'exports.pkg = require("pkg").name;\n', "node_modules/pkg/index.js": 'exports.name = "the package in node_modules";\n', "node_modules/pkg/package.json": '{ "name": "pkg", "version": "1.0.0", "main": "index.js" }\n'})
case("the-hook-is-set-by-a-required-file", 'require("./register.js"); say(attempt(() => require("@alias/lib.js")), attempt(() => require("./user.js")));', {"register.js": 'const Module = require("node:module"), path = require("node:path"); const old = Module._resolveFilename;\nModule._resolveFilename = function (request, ...rest) { if (request.startsWith("@alias/")) request = path.join(__dirname, request.slice(7)); return old.call(this, request, ...rest); };\n', "user.js": 'exports.lib = require("@alias/lib.js").name;\n'})
case("the-prototypes-require-is-replaced", 'const old = Module.prototype.require; const seen = [];\nModule.prototype.require = function (request) { seen.push(request); if (request === "./dep.js") return { name: "a stub from the prototype" }; return old.apply(this, arguments); };\nsay(require("./lib.js"), seen); Module.prototype.require = old;')
case("the-cache-is-written-to", 'const key = require.resolve("./dep.js");\nrequire.cache[key] = { id: key, filename: key, loaded: true, exports: { name: "a stub in the cache" } };\nsay(require("./lib.js"), require("./dep.js"));')
case("the-cache-is-written-to-by-the-other-name", 'const key = require.resolve("./dep.js");\nModule._cache[key] = { id: key, filename: key, loaded: true, exports: { name: "a stub in _cache" } };\nsay(require("./lib.js"), Module._cache === require.cache);')
case("the-exports-in-the-cache-are-replaced", 'require("./dep.js"); require.cache[require.resolve("./dep.js")].exports = { name: "replaced in the cache" };\nsay(require("./lib.js"), require("./dep.js"));')
case("the-cache-is-emptied", 'const a = require("./lib.js"); for (const k of Object.keys(require.cache)) if (!k.endsWith("main.js")) delete require.cache[k];\nconst b = require("./lib.js"); say(a === b, a.name === b.name, Object.keys(require.cache).map(k => path.basename(k)).sort());')
case("what-the-cache-lists", 'require("./lib.js"); say(Object.keys(require.cache).map(k => path.basename(k)).sort(), require.cache[require.resolve("./lib.js")].children.map(c => path.basename(c.id)), require.cache[require.resolve("./dep.js")].loaded, path.basename(require.cache[require.resolve("./dep.js")].parent?.id ?? "none"));')
case("wrap-and-wrapper", 'say(typeof Module.wrap, attempt(() => Module.wrap("x")), attempt(() => Module.wrapper));\nconst old = Module.wrap; Module.wrap = function (text) { return old(text.replace("the real", "the wrapped")); }; say(require("./lib.js")); Module.wrap = old;')
case("compile-by-hand", 'const m = new Module(path.join(__dirname, "virtual.js"), module); m.filename = m.id; m.paths = module.paths;\nsay(attempt(() => { m._compile(\'exports.name = "virtual"; exports.dep = require("./dep.js").name; exports.file = require("node:path").basename(__filename);\', m.filename); return m.exports; }));')
case("create-require", 'const r = Module.createRequire(path.join(__dirname, "sub", "anything.js"));\nsay(r("./inner.js"), r("../lib.js") === require("./lib.js"), path.basename(r.resolve("./inner.js")), typeof r.cache, r.cache === require.cache, r.main === require.main);', {"sub/inner.js": 'exports.name = "inner"; exports.up = require("../dep.js").name;\n'})
case("module-require-and-call", 'say(module.require("./lib.js") === require("./lib.js"), require.call(null, "./dep.js").name, require.apply(module, ["./dep.js"]).name, [ "./dep.js" ].map(require)[0].name, (0, require)("./dep.js").name); const r = require; say(r("./dep.js").name);')
case("a-name-computed-at-run-time", 'const names = ["lib", "dep"]; say(names.map(n => require("./" + n + ".js").name), attempt(() => require("./" + ["missing"][0] + ".js")), attempt(() => require(path.join(__dirname, "dep.js")).name), attempt(() => require(`./${names[1]}`).name));')
case("resolve-and-its-options", 'say(path.basename(require.resolve("./lib.js")), path.basename(require.resolve("./lib")), attempt(() => require.resolve("./missing.js")), attempt(() => path.basename(require.resolve("./inner.js", { paths: [path.join(__dirname, "sub")] }))), Array.isArray(require.resolve.paths("x")), require.resolve("node:fs"), require.resolve("fs"));', {"sub/inner.js": 'exports.name = "inner";\n'})
case("register-hooks", 'say(typeof Module.registerHooks, typeof Module.register, typeof Module.builtinModules, Module.isBuiltin("fs"), typeof Module.findSourceMap, typeof Module.syncBuiltinESMExports, typeof Module.SourceMap, typeof Module.globalPaths, typeof Module._nodeModulePaths, typeof Module._extensions, Module._extensions === require.extensions, typeof Module._findPath, typeof Module._initPaths, typeof Module.runMain, typeof Module.Module, Module.Module === Module);')
case("the-main-module", 'say(require.main === module, module.id, path.basename(module.filename), module.loaded, module.parent ?? null, module.children.length, path.basename(process.argv[1] ?? ""), process.mainModule === module, path.basename(require.main.filename)); require("./lib.js"); say(module.children.map(c => path.basename(c.id)));')
case("a-plugin-of-bun", 'say(attempt(() => { Bun.plugin({ name: "p", setup(build) { build.onLoad({ filter: /dep\\.js$/ }, () => ({ contents: \'exports.name = "a text of the plugin";\', loader: "js" })); } }); return require("./lib.js"); }));')
case("a-virtual-module-of-bun", 'say(attempt(() => { Bun.plugin({ name: "v", setup(build) { build.module("virtual:thing", () => ({ exports: { name: "virtual" }, loader: "object" })); } }); return require("virtual:thing"); }));')
for name, files in cases.items():
    for f, text in files.items():
        os.makedirs(os.path.dirname(f"{out}/{name}/{f}"), exist_ok=True); open(f"{out}/{name}/{f}", "w").write(text)
print(len(cases), "cases")
